// Generated by GitHub Copilot
/**
 * Helix — Wealth Management Assistant UI controller.
 * Talks to the FastAPI backend over:
 *   - REST POST /api/v1/agent/chat          – send a message, receive response
 *   - REST GET  /api/v1/agent/sessions      – list server-side sessions
 *   - REST DELETE /api/v1/agent/sessions/:id – delete a session
 *   - REST GET  /api/v1/agent/clients       – load client dropdown
 *
 * All DOM writes use textContent or safe builders → XSS-safe.
 * Sessions are also mirrored to localStorage for instant load on refresh.
 */
(() => {
  "use strict";

  /* ================ constants ================ */
  const API_BASE        = "/api/v1/agent";
  const SESSIONS_KEY    = "wm_sessions_v1";
  const MAX_SESSIONS    = 5;
  const MAX_MESSAGES    = 10; // pairs per session kept in localStorage
  const MAX_SESSION_BYTES = 60_000;
  const SVG_NS = "http://www.w3.org/2000/svg";

  /* ================ helper ================ */
  const $ = (id) => document.getElementById(id);

  const nowTime = () =>
    new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });

  /* ================ safe markdown → DOM ================ */
  /**
   * Minimal SAFE markdown → DOM converter. Never uses innerHTML.
   * Supports headings, tables, bullet/numbered lists, inline code, bold, italic.
   */
  function renderMarkdown(text, root) {
    if (!text) return;
    const lines = text.replace(/\r\n/g, "\n").split("\n");
    let i = 0;
    while (i < lines.length) {
      const line  = lines[i];
      const trimmed = line.trim();
      if (!trimmed) { i++; continue; }

      if (/^-{3,}$|^_{3,}$|^\*{3,}$/.test(trimmed)) {
        root.appendChild(document.createElement("hr")); i++; continue;
      }

      const hMatch = /^(#{1,4})\s+(.+?)\s*#*\s*$/.exec(trimmed);
      if (hMatch) {
        const h = document.createElement(`h${hMatch[1].length + 2}`);
        renderInline(hMatch[2], h); root.appendChild(h); i++; continue;
      }

      if (/^\|.+\|$/.test(trimmed) && i + 1 < lines.length
          && /^\|[\s:|\-]+\|$/.test(lines[i + 1].trim())) {
        const headerCells = splitTableRow(trimmed);
        const table = document.createElement("table");
        table.className = "md-table";
        const thead = document.createElement("thead");
        const headerTr = document.createElement("tr");
        headerCells.forEach((c) => { const th = document.createElement("th"); renderInline(c, th); headerTr.appendChild(th); });
        thead.appendChild(headerTr); table.appendChild(thead);
        const tbody = document.createElement("tbody");
        i += 2;
        while (i < lines.length && /^\|.+\|$/.test(lines[i].trim())) {
          const cells = splitTableRow(lines[i].trim());
          const tr = document.createElement("tr");
          cells.forEach((c) => { const td = document.createElement("td"); renderInline(c, td); tr.appendChild(td); });
          tbody.appendChild(tr); i++;
        }
        table.appendChild(tbody); root.appendChild(table); continue;
      }

      if (/^[-*]\s+/.test(trimmed)) {
        const ul = document.createElement("ul");
        while (i < lines.length && /^[-*]\s+/.test(lines[i].trim())) {
          const li = document.createElement("li");
          renderInline(lines[i].trim().replace(/^[-*]\s+/, ""), li);
          ul.appendChild(li); i++;
        }
        root.appendChild(ul); continue;
      }

      if (/^\d+\.\s+/.test(trimmed)) {
        const ol = document.createElement("ol");
        while (i < lines.length && /^\d+\.\s+/.test(lines[i].trim())) {
          const li = document.createElement("li");
          renderInline(lines[i].trim().replace(/^\d+\.\s+/, ""), li);
          ol.appendChild(li); i++;
        }
        root.appendChild(ol); continue;
      }

      const p = document.createElement("p");
      const buf = [];
      while (i < lines.length && lines[i].trim()
             && !/^#{1,4}\s/.test(lines[i].trim())
             && !/^[-*]\s+/.test(lines[i].trim())
             && !/^\d+\.\s+/.test(lines[i].trim())
             && !/^\|.+\|$/.test(lines[i].trim())
             && !/^-{3,}$|^_{3,}$|^\*{3,}$/.test(lines[i].trim())) {
        buf.push(lines[i]); i++;
      }
      buf.forEach((l, idx) => {
        renderInline(l, p);
        if (idx < buf.length - 1) p.appendChild(document.createElement("br"));
      });
      root.appendChild(p);
    }
  }

  function splitTableRow(line) {
    const trimmed = line.trim().replace(/^\|/, "").replace(/\|$/, "");
    const parts = []; let cur = "";
    for (let i = 0; i < trimmed.length; i++) {
      const ch = trimmed[i];
      if (ch === "\\" && trimmed[i + 1] === "|") { cur += "|"; i++; continue; }
      if (ch === "|") { parts.push(cur.trim()); cur = ""; continue; }
      cur += ch;
    }
    parts.push(cur.trim()); return parts;
  }

  function renderInline(text, parent) {
    const re = /(`[^`]+`)|(\[[^\]\n]+?\]\((?:https?:\/\/|mailto:)[^\s)]+\))|(https?:\/\/[^\s<>"')\]]+)|(\*\*[^*\n]+?\*\*)|(\*[^*\n]+?\*)|(_[^_\n]+?_)/g;
    let last = 0, m;
    while ((m = re.exec(text)) !== null) {
      if (m.index > last) parent.appendChild(document.createTextNode(text.slice(last, m.index)));
      const tok = m[0]; let el;
      if (tok.startsWith("`")) { el = document.createElement("code"); el.textContent = tok.slice(1, -1); }
      else if (tok.startsWith("[")) {
        const cb = tok.indexOf("]("), label = tok.slice(1, cb), href = tok.slice(cb + 2, -1);
        el = makeSafeLink(href, label);
      } else if (/^https?:\/\//.test(tok)) { el = makeSafeLink(tok, tok); }
      else if (tok.startsWith("**")) { el = document.createElement("strong"); el.textContent = tok.slice(2, -2); }
      else { el = document.createElement("em"); el.textContent = tok.startsWith("_") ? tok.slice(1, -1) : tok.slice(1, -1); }
      parent.appendChild(el);
      last = m.index + tok.length;
    }
    if (last < text.length) parent.appendChild(document.createTextNode(text.slice(last)));
  }

  function makeSafeLink(href, label) {
    if (!/^(?:https?:\/\/|mailto:)/i.test(href)) {
      const s = document.createElement("span"); s.textContent = label; return s;
    }
    const a = document.createElement("a");
    a.href = href; a.textContent = label;
    a.target = "_blank"; a.rel = "noopener noreferrer"; return a;
  }

  /* ================ DOM refs ================ */
  const chatLog        = $("chat-log");
  const emptyChat      = $("empty-chat");
  const chatForm       = $("chat-form");
  const chatInput      = $("chat-input");
  const btnSend        = $("btn-send");
  const btnNewChat     = $("btn-new-chat");
  const btnTheme       = $("btn-theme");
  const charCount      = $("char-count");
  const clientSelect   = $("client-select");
  const sessionList    = $("session-list");
  const btnClearAll    = $("btn-clear-sessions");
  const modelBadge        = $("model-badge");
  const runStatus         = $("run-status");
  const agentTimeline     = $("agent-timeline");
  const toastRoot         = $("toast-root");
  const topbarTitle       = $("topbar-title");
  const footerModel       = $("footer-model");
  const activityLog       = $("activity-log");
  const activityLive      = $("activity-live");

  /* ================ state ================ */
  let sessions         = [];
  let currentSessionId = null;
  let history          = [];       // [{role, content}] mirrored for current session
  let isBusy           = false;
  let emptyEl          = emptyChat; // track removal

  /* ================ theme ================ */
  const html = document.documentElement;
  const savedTheme = localStorage.getItem("wm_theme") || "light";
  html.dataset.theme = savedTheme;

  btnTheme.addEventListener("click", () => {
    const next = html.dataset.theme === "light" ? "dark" : "light";
    html.dataset.theme = next;
    localStorage.setItem("wm_theme", next);
  });

  /* ================ char counter ================ */
  chatInput.addEventListener("input", () => {
    const len = chatInput.value.length;
    charCount.textContent = `${len} / 2000`;
    btnSend.disabled = isBusy || !chatInput.value.trim();
    autoResize(chatInput);
  });

  function autoResize(el) {
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 160)}px`;
  }

  /* ================ keyboard shortcuts ================ */
  chatInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      if (!isBusy && chatInput.value.trim()) chatForm.requestSubmit();
    }
  });

  /* ================ suggestions ================ */
  document.querySelectorAll(".suggestion").forEach((btn) => {
    btn.addEventListener("click", () => {
      chatInput.value = btn.dataset.prompt || "";
      chatInput.dispatchEvent(new Event("input"));
      chatInput.focus();
    });
  });

  /* ================ new chat ================ */
  btnNewChat.addEventListener("click", () => startNewSession());

  /* ================ clear all sessions ================ */
  btnClearAll.addEventListener("click", () => {
    if (!confirm("Delete all saved chat sessions?")) return;
    sessions = [];
    localStorage.removeItem(SESSIONS_KEY);
    currentSessionId = null;
    history.length = 0;
    chatLog.innerHTML = "";
    if (!emptyEl) { emptyEl = document.createElement("div"); emptyEl.id = "empty-chat"; emptyEl.className = "welcome"; chatLog.appendChild(emptyEl); }
    resetTimeline("idle");
    startNewSession();
  });

  /* ================ client list ================ */
  async function loadClients() {
    try {
      const res = await fetch(`${API_BASE}/clients`);
      if (!res.ok) return;
      const data = await res.json();
      const clients = data.clients || [];
      clients.forEach((c) => {
        const opt = document.createElement("option");
        opt.value = typeof c === "object" ? (c.id || c.client_id || c.name) : c;
        opt.textContent = typeof c === "object" ? (c.name || c.client_name || opt.value) : c;
        clientSelect.appendChild(opt);
      });
    } catch (err) { console.warn("Could not load clients:", err); }
  }

  /* ================ app info (dynamic header values from .env) ================ */
  async function loadModelInfo() {
    try {
      const res = await fetch(`${API_BASE}/info`);
      if (!res.ok) return;
      const data = await res.json();
      const model   = data.model   || "Gemini";
      const appName = data.app_name || "Wealth Management Assistant";
      // Update model badge in topbar
      modelBadge.textContent = model;
      // Update footer model label
      if (footerModel) footerModel.textContent = `LangGraph · ${model}`;
    } catch (_) {
      modelBadge.textContent = "Gemini";
    }
  }

  /* ================ session manager ================ */
  function loadSessions() {
    try {
      const raw = localStorage.getItem(SESSIONS_KEY);
      sessions = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(sessions)) sessions = [];
      sessions = sessions.filter(
        (s) => s && typeof s === "object" && typeof s.id === "string" && Array.isArray(s.history)
      );
    } catch (_) { sessions = []; }
  }

  function persistSessions() {
    try {
      localStorage.setItem(SESSIONS_KEY, JSON.stringify(sessions));
    } catch (_) {
      while (sessions.length > 1) {
        sessions.pop();
        try { localStorage.setItem(SESSIONS_KEY, JSON.stringify(sessions)); return; } catch (_) { /* shrink */ }
      }
      try { localStorage.removeItem(SESSIONS_KEY); } catch (_) { /* ignore */ }
    }
  }

  function pruneSessionHistory(s) {
    if (!s || !Array.isArray(s.history)) return;
    if (s.history.length > MAX_MESSAGES * 2) s.history = s.history.slice(-MAX_MESSAGES * 2);
    while (s.history.length > 2 && JSON.stringify(s.history).length > MAX_SESSION_BYTES) {
      s.history.splice(0, 2);
    }
  }

  function startNewSession() {
    const id = `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
    const s = { id, title: "New chat", updatedAt: Date.now(), history: [] };
    sessions.unshift(s);
    if (sessions.length > MAX_SESSIONS) sessions = sessions.slice(0, MAX_SESSIONS);
    currentSessionId = id;
    history.length = 0;
    persistSessions();
    // Reset chat view
    chatLog.innerHTML = "";
    const welcome = buildWelcome();
    chatLog.appendChild(welcome);
    emptyEl = welcome;
    resetTimeline("idle");
    renderSessionList();
    chatInput.focus();
    return s;
  }

  function ensureSession() {
    const s = sessions.find((x) => x.id === currentSessionId);
    return s || startNewSession();
  }

  function recordTurn(role, content) {
    if (!content) return;
    const s = ensureSession();
    s.history.push({ role, content });
    if (role === "user" && s.title === "New chat") {
      s.title = content.length > 60 ? content.slice(0, 57).trim() + "\u2026" : content;
    }
    s.updatedAt = Date.now();
    pruneSessionHistory(s);
    history.length = 0;
    s.history.forEach((h) => history.push(h));
    sessions = [s, ...sessions.filter((x) => x.id !== s.id)];
    persistSessions();
    renderSessionList();
  }

  /**
   * Fetch server-side sessions and merge any unknown ones into localStorage.
   * Sessions already in localStorage are left untouched (local copy wins).
   * Unknown server sessions are added as skeletons; their history is fetched
   * lazily when the user clicks on them.
   */
  async function syncSessionsFromServer() {
    try {
      const res = await fetch(`${API_BASE}/sessions`);
      if (!res.ok) return;
      const serverSessions = await res.json();
      if (!Array.isArray(serverSessions) || serverSessions.length === 0) return;

      const localIds = new Set(sessions.map((s) => s.id));
      let added = false;

      for (const ss of serverSessions) {
        const sid = ss.session_id;
        if (!sid || localIds.has(sid)) continue;
        if (!ss.history_count || ss.history_count === 0) continue;

        const updatedAt = ss.last_updated ? new Date(ss.last_updated).getTime() : Date.now();
        const dateLabel = ss.last_updated
          ? new Date(ss.last_updated).toLocaleDateString()
          : "";
        sessions.push({
          id: sid,
          title: `Saved chat${dateLabel ? " · " + dateLabel : ""}`,
          updatedAt,
          history: [],
          _serverSynced: true,  // flag: history must be loaded from server on first access
        });
        localIds.add(sid);
        added = true;
      }

      if (added) {
        sessions.sort((a, b) => b.updatedAt - a.updatedAt);
        if (sessions.length > MAX_SESSIONS) sessions = sessions.slice(0, MAX_SESSIONS);
        persistSessions();
        renderSessionList();
      }
    } catch (err) {
      console.warn("syncSessionsFromServer: could not reach server sessions API", err);
    }
  }

  async function loadSession(id) {
    const s = sessions.find((x) => x.id === id);
    if (!s) return;
    currentSessionId = id;
    history.length = 0;
    chatLog.innerHTML = "";
    emptyEl = null;

    // Lazily fetch history from server for sessions that were not in localStorage
    if (s._serverSynced && s.history.length === 0) {
      try {
        const res = await fetch(`${API_BASE}/sessions/${encodeURIComponent(id)}`);
        if (res.ok) {
          const data = await res.json();
          s.history = (data.history || []).map((h) => ({
            role: h.role,
            content: h.content,
          }));
          s._serverSynced = false;
          // Derive a meaningful title from the first user message
          const firstUser = s.history.find((h) => h.role === "user");
          if (firstUser) {
            s.title = firstUser.content.length > 60
              ? firstUser.content.slice(0, 57).trim() + "\u2026"
              : firstUser.content;
          }
          pruneSessionHistory(s);
          persistSessions();
        }
      } catch (err) {
        console.warn("loadSession: failed to fetch history from server", err);
      }
    }

    s.history.forEach((h) => {
      history.push(h);
      if (h.role === "user")      appendMessage("user", h.content);
      else if (h.role === "assistant") appendMessage("assistant", h.content);
    });
    resetTimeline("idle");
    renderSessionList();
    chatInput.focus();
  }

  function deleteSession(id) {
    sessions = sessions.filter((s) => s.id !== id);
    persistSessions();
    if (currentSessionId === id) {
      currentSessionId = null;
      history.length = 0;
      startNewSession();
    } else {
      renderSessionList();
    }
  }

  function formatRelative(ts) {
    const diff = (Date.now() - ts) / 1000;
    if (diff < 45)    return "now";
    if (diff < 3600)  return `${Math.floor(diff / 60)}m`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h`;
    return `${Math.floor(diff / 86400)}d`;
  }

  function renderSessionList() {
    if (!sessionList) return;
    sessionList.innerHTML = "";
    if (!sessions.length) {
      const li = document.createElement("li"); li.className = "empty-state";
      li.textContent = "No saved chats yet"; sessionList.appendChild(li); return;
    }
    sessions.forEach((s) => {
      const li   = document.createElement("li");
      li.className = "session-item" + (s.id === currentSessionId ? " is-active" : "");
      li.setAttribute("role", "button"); li.tabIndex = 0;
      const title = document.createElement("span"); title.className = "session-title";
      title.textContent = s.title || "(untitled)"; title.title = title.textContent;
      const meta = document.createElement("span"); meta.className = "session-meta";
      meta.textContent = formatRelative(s.updatedAt);
      const del = document.createElement("button"); del.type = "button";
      del.className = "session-del";
      del.setAttribute("aria-label", `Delete chat "${s.title || "untitled"}"`);
      del.textContent = "\u00d7";
      del.addEventListener("click", (e) => {
        e.stopPropagation();
        if (confirm("Delete this saved chat?")) deleteSession(s.id);
      });
      li.append(title, meta, del);
      li.addEventListener("click", () => loadSession(s.id));
      li.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); loadSession(s.id); }
      });
      sessionList.appendChild(li);
    });
  }

  /* ================ welcome screen builder ================ */
  function buildWelcome() {
    const d = document.createElement("div");
    d.id = "empty-chat"; d.className = "welcome";
    d.innerHTML = `
      <div class="welcome-icon" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"
             stroke-linecap="round" stroke-linejoin="round">
          <circle cx="12" cy="12" r="3"/>
          <path d="M12 1v6M12 17v6M4.22 4.22l4.24 4.24M15.54 15.54l4.24 4.24M1 12h6M17 12h6"/>
        </svg>
      </div>
      <h2 class="welcome-title">Your AI wealth-management co-pilot.</h2>
      <p class="welcome-subtitle">Select a client and ask about their portfolio, CRM activity, or risk profile.</p>
    `;
    return d;
  }

  /* ================ agent timeline ================ */
  const AGENT_LABELS = {
    router:                    { label: "Routing query",       icon: "🔀" },
    portfolio_insights:        { label: "Portfolio Insights",  icon: "📊" },
    relationship_intelligence: { label: "Relationship Intel.", icon: "🤝" },
    general:                   { label: "Direct response",     icon: "💬" },
    needs_clarification:       { label: "Clarifying query",    icon: "❓" },
    done:                      { label: "Response ready",      icon: "✅" },
    error:                     { label: "Error encountered",   icon: "⚠️" },
  };

  function resetTimeline(statusText) {
    agentTimeline.innerHTML = `<li class="agent-empty">Send a question to see the multi-agent workflow execute step-by-step.</li>`;
    runStatus.textContent = statusText || "idle";
    runStatus.className = `badge badge-${statusText === "idle" ? "pending" : statusText === "done" ? "model" : "warning"}`;
  }

  function timelineStep(nodeKey, state) {
    const cfg = AGENT_LABELS[nodeKey] || { label: nodeKey, icon: "⚙️" };
    const prev = agentTimeline.querySelector(".agent-empty");
    if (prev) prev.remove();

    let li = agentTimeline.querySelector(`[data-node="${nodeKey}"]`);
    if (!li) {
      li = document.createElement("li");
      li.className = "timeline-item";
      li.dataset.node = nodeKey;
      li.setAttribute("role", "listitem");

      const nameRow = document.createElement("div");
      nameRow.className = "timeline-agent-name";

      const labelSpan = document.createElement("span");
      labelSpan.textContent = `${cfg.icon}  ${cfg.label}`;

      const timeSpan = document.createElement("span");
      timeSpan.className = "timeline-time";
      timeSpan.textContent = nowTime();

      nameRow.append(labelSpan, timeSpan);
      li.appendChild(nameRow);
      agentTimeline.appendChild(li);
    }

    // Update state classes
    li.classList.remove("is-running", "is-done", "is-error");
    if (state === "running")  li.classList.add("is-running");
    else if (state === "done") li.classList.add("is-done");
    else if (state === "error") li.classList.add("is-error");

    return li;
  }

  /* ================ toast ================ */
  function toast(message, { kind = "info", title } = {}) {
    const el = document.createElement("div");
    el.className = `toast is-${kind}`;
    el.setAttribute("role", "status");
    const body = document.createElement("div"); body.style.flex = "1";
    if (title) { const h = document.createElement("div"); h.className = "toast-title"; h.textContent = title; body.appendChild(h); }
    const p = document.createElement("div"); p.className = "toast-body"; p.textContent = message;
    body.appendChild(p); el.appendChild(body);
    toastRoot.appendChild(el);
    setTimeout(() => {
      el.style.transition = "opacity 0.3s, transform 0.3s";
      el.style.opacity = "0"; el.style.transform = "translateY(6px)";
      setTimeout(() => el.remove(), 320);
    }, 4500);
  }

  /* ================ messages ================ */
  function avatarFor(role) {
    const a = document.createElement("div");
    a.className = `avatar ${role}`;
    if (role === "user") { a.textContent = "Y"; return a; }
    if (role === "assistant") {
      const svg = document.createElementNS(SVG_NS, "svg");
      svg.setAttribute("viewBox", "0 0 24 24"); svg.setAttribute("fill", "none");
      svg.setAttribute("stroke", "currentColor"); svg.setAttribute("stroke-width", "2");
      svg.setAttribute("stroke-linecap", "round"); svg.setAttribute("stroke-linejoin", "round");
      const c = document.createElementNS(SVG_NS, "circle");
      c.setAttribute("cx", "12"); c.setAttribute("cy", "12"); c.setAttribute("r", "3");
      const p = document.createElementNS(SVG_NS, "path");
      p.setAttribute("d", "M12 1v6M12 17v6M4.22 4.22l4.24 4.24M15.54 15.54l4.24 4.24M1 12h6M17 12h6");
      svg.append(c, p); a.appendChild(svg); return a;
    }
    a.textContent = "!"; return a;
  }

  function appendMessage(role, content) {
    if (emptyEl) { try { emptyEl.remove(); } catch (_) { /* ignore */ } emptyEl = null; }
    const wrap = document.createElement("div"); wrap.className = `msg ${role}`;
    wrap.appendChild(avatarFor(role));
    const bubble = document.createElement("div"); bubble.className = "bubble";
    const metaEl = document.createElement("div"); metaEl.className = "bubble-meta";
    const who = document.createElement("strong");
    who.textContent = role === "user" ? "You" : role === "assistant" ? "Helix" : "Error";
    metaEl.appendChild(who);
    const time = document.createElement("span");
    time.textContent = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    metaEl.appendChild(time);
    bubble.appendChild(metaEl);
    const body = document.createElement("div"); body.className = "bubble-content";
    if (role === "assistant") renderMarkdown(content, body);
    else { const p = document.createElement("p"); p.textContent = content; body.appendChild(p); }
    bubble.appendChild(body);
    wrap.appendChild(bubble);
    chatLog.appendChild(wrap);
    chatLog.scrollTop = chatLog.scrollHeight;
    return wrap;
  }

  /* ================ thinking animation ================ */
  let thinkingEl = null;
  let thinkTickId = null;

  function mountThinking() {
    if (thinkingEl) return thinkingEl;
    if (emptyEl) { try { emptyEl.remove(); } catch (_) { /* ignore */ } emptyEl = null; }

    const wrap = document.createElement("div"); wrap.className = "msg assistant thinking";
    wrap.appendChild(avatarFor("assistant"));
    const card = document.createElement("div"); card.className = "thinking-card";
    const header = document.createElement("div"); header.className = "thinking-header";
    const ring = document.createElement("span"); ring.className = "thinking-ring"; ring.setAttribute("aria-hidden", "true");
    const titleEl = document.createElement("span"); titleEl.className = "thinking-title"; titleEl.textContent = "Thinking\u2026";
    const elapsed = document.createElement("span"); elapsed.className = "thinking-elapsed"; elapsed.textContent = "0.0s";
    header.append(ring, titleEl, elapsed);
    const steps = document.createElement("ul"); steps.className = "thinking-steps";
    steps.setAttribute("role", "status"); steps.setAttribute("aria-live", "polite");
    card.append(header, steps);
    wrap.appendChild(card);
    chatLog.appendChild(wrap);
    chatLog.scrollTop = chatLog.scrollHeight;

    const startedAt = performance.now();
    thinkTickId = setInterval(() => {
      elapsed.textContent = `${((performance.now() - startedAt) / 1000).toFixed(1)}s`;
    }, 100);
    thinkingEl = { wrap, card, titleEl, steps, elapsed };
    return thinkingEl;
  }

  function thinkingAddStep(label, state) {
    if (!thinkingEl) return;
    const li = document.createElement("li"); li.className = `thinking-step ${state === "active" ? "is-active" : "is-done"}`;
    const icon = document.createElement("span"); icon.className = "step-icon"; icon.setAttribute("aria-hidden", "true");
    const labelEl = document.createElement("span"); labelEl.className = "step-label"; labelEl.textContent = label;
    li.append(icon, labelEl);
    thinkingEl.steps.appendChild(li);
    thinkingEl.titleEl.textContent = label + (state === "active" ? "\u2026" : "");
    chatLog.scrollTop = chatLog.scrollHeight;
  }

  function dismissThinking(state) {
    if (thinkTickId) { clearInterval(thinkTickId); thinkTickId = null; }
    if (!thinkingEl) return;
    const { wrap, card } = thinkingEl;
    if (state === "done") {
      card.classList.add("is-done");
      wrap.style.transition = "opacity 0.25s ease, transform 0.25s ease";
      requestAnimationFrame(() => { wrap.style.opacity = "0"; wrap.style.transform = "translateY(-4px)"; });
      setTimeout(() => { try { wrap.remove(); } catch (_) { /* ignore */ } }, 260);
    } else {
      // Show error state briefly then remove so the error bubble is visible
      card.classList.add("is-error");
      wrap.style.transition = "opacity 0.35s ease, transform 0.35s ease";
      setTimeout(() => {
        requestAnimationFrame(() => { wrap.style.opacity = "0"; wrap.style.transform = "translateY(-4px)"; });
        setTimeout(() => { try { wrap.remove(); } catch (_) { /* ignore */ } }, 370);
      }, 700);
    }
    thinkingEl = null;
  }

  /* ================ activity log ================ */
  const ICON_MAP = {
    route: "🔀", agent: "🤖", tool: "🔧", write: "✍️", check: "✅", error: "❌",
  };

  function clearActivityLog() {
    if (!activityLog) return;
    activityLog.innerHTML = "";
    if (activityLive) { activityLive.className = "activity-live is-active"; }
  }

  function addActivityEntry(icon, msg, done) {
    if (!activityLog) return;
    // Remove empty placeholder if present
    const empty = activityLog.querySelector(".activity-empty");
    if (empty) empty.remove();

    const li = document.createElement("li");
    li.className = `activity-item ${done ? "is-done" : "is-active"}`;

    const iconEl = document.createElement("span");
    iconEl.className = `activity-icon icon-${icon}`;
    iconEl.textContent = ICON_MAP[icon] || "•";
    iconEl.setAttribute("aria-hidden", "true");

    const body = document.createElement("div");
    body.className = "activity-body";

    const msgEl = document.createElement("span");
    msgEl.className = "activity-msg";
    msgEl.textContent = msg;

    const timeEl = document.createElement("span");
    timeEl.className = "activity-time";
    timeEl.textContent = nowTime();

    body.append(msgEl, timeEl);
    li.append(iconEl, body);
    activityLog.appendChild(li);
    activityLog.scrollTop = activityLog.scrollHeight;
  }

  function finishActivityLog() {
    if (activityLive) { activityLive.className = "activity-live"; }
    // Mark any remaining active items as done
    activityLog?.querySelectorAll(".activity-item.is-active").forEach(
      el => el.classList.replace("is-active", "is-done")
    );
  }

  /* ================ busy guard ================ */
  function setSendBusy(busy) {
    isBusy = busy;
    btnSend.disabled = busy || !chatInput.value.trim();
    chatInput.disabled = busy;
  }

  /* ================ streaming message bubble ================ */
  /**
   * Create an empty assistant bubble and return refs to its body.
   * Tokens are appended as raw text nodes; on stream completion
   * the body is re-rendered with full markdown formatting.
   */
  function mountStreamBubble() {
    if (emptyEl) { try { emptyEl.remove(); } catch (_) { /* ignore */ } emptyEl = null; }
    const wrap   = document.createElement("div"); wrap.className = "msg assistant";
    wrap.appendChild(avatarFor("assistant"));

    const bubble = document.createElement("div"); bubble.className = "bubble";
    const metaEl = document.createElement("div"); metaEl.className = "bubble-meta";
    const who    = document.createElement("strong"); who.textContent = "Helix";
    const time   = document.createElement("span");
    time.textContent = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    metaEl.append(who, time);
    bubble.appendChild(metaEl);

    const body = document.createElement("div"); body.className = "bubble-content";
    // Live text container — tokens stream into here as a single <p>
    const liveP = document.createElement("p");
    liveP.className = "stream-text";
    body.appendChild(liveP);
    bubble.appendChild(body);
    wrap.appendChild(bubble);
    chatLog.appendChild(wrap);
    chatLog.scrollTop = chatLog.scrollHeight;
    return { wrap, body, liveP };
  }

  /** Append a raw text token to the live paragraph. */
  function appendToken(liveP, token) {
    liveP.appendChild(document.createTextNode(token));
    chatLog.scrollTop = chatLog.scrollHeight;
  }

  /** Replace raw streamed text with properly rendered markdown. */
  function finaliseStreamBubble(body, liveP, fullText) {
    body.removeChild(liveP);
    renderMarkdown(fullText, body);
    chatLog.scrollTop = chatLog.scrollHeight;
  }

  /* ================ SSE stream parser ================ */
  /**
   * Parse raw SSE bytes from a ReadableStream and call `onEvent(data)`
   * for each complete ``data: <json>`` event line.
   */
  async function consumeSSE(readableStream, onEvent) {
    const reader  = readableStream.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        // SSE events are separated by double newlines
        const parts = buffer.split("\n\n");
        buffer = parts.pop(); // last (possibly incomplete) chunk stays in buffer
        for (const part of parts) {
          for (const line of part.split("\n")) {
            if (line.startsWith("data: ")) {
              try {
                onEvent(JSON.parse(line.slice(6)));
              } catch (_) { /* malformed JSON — skip */ }
            }
          }
        }
      }
    } finally {
      reader.releaseLock();
    }
  }

  /* ================ chat submit ================ */
  chatForm.addEventListener("submit", async (e) => {
    e.preventDefault();
    const query = chatInput.value.trim();
    if (!query || isBusy) return;

    const sessionId = ensureSession().id;
    const clientId  = clientSelect.value || null;

    // Show user message immediately
    appendMessage("user", query);
    recordTurn("user", query);
    chatInput.value = "";
    chatInput.style.height = "auto";
    charCount.textContent = "0 / 2000";
    setSendBusy(true);

    // Reset timeline and activity log
    agentTimeline.innerHTML = "";
    runStatus.textContent = "running";
    runStatus.className = "badge badge-warning";
    timelineStep("router", "running");
    clearActivityLog();

    // Thinking card while we wait for first token
    mountThinking();
    thinkingAddStep("Routing query\u2026", "active");

    const payload = {
      message: query,
      session_id: sessionId,
      metadata: clientId ? { client_id: clientId } : {},
    };

    let streamBubble = null; // { wrap, body, liveP }
    let fullText     = "";
    let agentUsed    = "unknown";
    let thinkingDismissed = false;

    try {
      const res = await fetch(`${API_BASE}/stream`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const err = await res.json().catch(() => ({ detail: `HTTP ${res.status}` }));
        throw new Error(err.detail || `HTTP ${res.status}`);
      }

      await consumeSSE(res.body, (event) => {
        const { type } = event;

        if (type === "step") {
          timelineStep(event.node, event.state);
          if (event.node !== "router") {
            thinkingAddStep(
              `${AGENT_LABELS[event.node]?.label || event.node}${event.state === "running" ? "\u2026" : ""}`,
              event.state === "running" ? "active" : "done"
            );
          }

        } else if (type === "activity") {
          addActivityEntry(event.icon || "check", event.msg || "", event.done === true);

        } else if (type === "token") {
          // Dismiss thinking card on the very first token
          if (!thinkingDismissed) {
            dismissThinking("done");
            thinkingDismissed = true;
          }
          // Create the bubble on the first token
          if (!streamBubble) streamBubble = mountStreamBubble();
          fullText += event.content;
          appendToken(streamBubble.liveP, event.content);

        } else if (type === "done") {
          agentUsed = event.agent_used || "unknown";
          fullText  = event.full_response || fullText;
          // Finalise: re-render full markdown
          if (streamBubble) {
            finaliseStreamBubble(streamBubble.body, streamBubble.liveP, fullText);
          }
          timelineStep("done", "done");
          runStatus.textContent = "done";
          runStatus.className = "badge badge-model";
          finishActivityLog();
          recordTurn("assistant", fullText);

        } else if (type === "error") {
          throw new Error(event.message || "Streaming error");
        }
      });

      // Safety net: if no token was ever received (e.g. very short response
      // that arrived as a single done event without preceding tokens)
      if (!streamBubble && fullText) {
        appendMessage("assistant", fullText);
        recordTurn("assistant", fullText);
      }
      if (!thinkingDismissed) dismissThinking("done");

    } catch (err) {
      console.error("Stream error:", err);
      if (!thinkingDismissed) dismissThinking("error");
      timelineStep("error", "error");
      runStatus.textContent = "error";
      runStatus.className = "badge badge-warning";
      addActivityEntry("error", `Error: ${err.message || "request failed"}`, true);
      finishActivityLog();
      appendMessage("error", `Error: ${err.message || "Something went wrong. Please try again."}`);
      toast(err.message || "Request failed", { kind: "error", title: "Chat error" });
    } finally {
      setSendBusy(false);
      chatInput.focus();
    }
  });

  /* ================ init ================ */
  function init() {
    loadSessions();

    if (!sessions.length) {
      startNewSession();
    } else {
      currentSessionId = sessions[0].id;
      history.length = 0;
      sessions[0].history.forEach((h) => history.push(h));
      renderSessionList();
      // If the most recent session has history, render it
      if (sessions[0].history.length > 0) {
        chatLog.innerHTML = "";
        emptyEl = null;
        sessions[0].history.forEach((h) => {
          if (h.role === "user") appendMessage("user", h.content);
          else if (h.role === "assistant") appendMessage("assistant", h.content);
        });
      }
    }

    loadClients();
    loadModelInfo();

    // Background sync: pull any server-side sessions missing from localStorage.
    // Runs after the initial paint so it never blocks the UI.
    syncSessionsFromServer();
  }

  init();
})();
